-- prisma/seed.sql: made-up sample data. Never for a live database.
-- Where it is loaded: a review copy and a public preview of this site, the staging database
-- when the owner presses "Load sample data" (never their live one), and your own machine with
-- `npx prisma db seed`. No users and no roles: people sign up. Safe to run twice, all or nothing.
-- Two published IntelForm forms (built from the built-in "Contact / support" and "NPS"
-- templates) with a few responses. Every address is @example.com. The contact_* columns are
-- filled by the responses_contact_fill trigger: never set them here.
BEGIN;

-- Stop when real data is there: IntelForm is already in use.
DO $$
BEGIN
  IF EXISTS (
    SELECT 1 FROM "forms"
    WHERE "id" NOT IN ('00000000-0000-4000-8000-00000000f001', '00000000-0000-4000-8000-00000000f002')
  ) OR EXISTS (
    SELECT 1 FROM "responses"
    WHERE "form_id" NOT IN ('00000000-0000-4000-8000-00000000f001', '00000000-0000-4000-8000-00000000f002')
  ) THEN
    RAISE EXCEPTION 'prisma/seed.sql is sample data and IntelForm is already in use. Nothing was changed.';
  END IF;
END $$;

-- Fixed ids and ON CONFLICT DO NOTHING: safe to run twice.
